from collections import deque

class Solution:

	def wordLadderLength(self, startWord, targetWord, wordList):
		queue = deque()
		queue.append((startWord, 1))
		visited_set = set(wordList)
		if startWord in visited_set:
			visited_set.remove(startWord)
		while queue:
			(word, steps) = queue.popleft()
			if word == targetWord:
				return steps
			word = list(word)
			for i in range(len(word)):
				originalletter = word[i]
				for ch in range(ord('a'), ord('z') + 1):
					word[i] = chr(ch)
					if ''.join(word) in visited_set:
						queue.append((''.join(word), steps + 1))
						visited_set.remove(''.join(word))
				word[i] = originalletter
		return 0
